def flatten_dict(nested: dict, sep: str = '.') -> dict:
    if not isinstance(nested, dict):
        raise TypeError("El argumento 'nested' debe ser un diccionario.")

    def flatten_helper(d, path=''):
        result = {}
        for key, value in d.items():
            new_path = f"{path}{sep}{key}" if path else key
            if isinstance(value, dict):
                result.update(flatten_helper(value, new_path))
            elif isinstance(value, list):
                for i, item in enumerate(value):
                    result.update(flatten_helper(item, f"{new_path}.{i}"))
            else:
                result[new_path] = value
        return result

    return flatten_helper(nested)

