def find_first_occurrence(nums: list[int], target: int) -> int:
    if not nums:
        return -1

    left = 0
    right = len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            # Check if this is the first occurrence
            if mid == 0 or nums[mid - 1] != target:
                return mid
            # If it's not the first occurrence, move left to find the first
            right = mid - 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

